58	import jakarta.transaction.Transactional;
59	
60	/**
61	 * @author Vitaliy Fedoriv
62	 */
63	
64	@RestController
65	@CrossOrigin(exposedHeaders = "errors, content-type")
66	@RequestMapping("/api")
67	public class OwnerRestControllerV1 implements OwnersApi {
68	
69	    /** Dedicated audit trail for owner-lifecycle side effects. */
70	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
71	
72	    /** Email domains from disposable/throwaway providers, rejected on create. */
73	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
74	        "mailinator.com", "tempmail.com", "guerrillamail.com");
75	
76	    /** Request header carrying an idempotency token for owner creation. */
77	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
78	
79	    /**
80	     * Remembers the owner created under each seen {@code Idempotency-Key}, so a repeated
81	     * create with an already-seen key returns the original owner (200) instead of creating
82	     * a duplicate. Keyed by the header value, mapped to the created owner's id.
83	     */
84	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
85	
86	    private final ClinicService clinicService;
87	
88	    private final OwnerMapper ownerMapper;
89	
90	    private final PetMapper petMapper;
91	
92	    private final VisitMapper visitMapper;
93	
94	    public OwnerRestControllerV1(ClinicService clinicService,
95	                                 OwnerMapper ownerMapper,
96	                                 PetMapper petMapper,
97	                                 VisitMapper visitMapper) {
98	        this.clinicService = clinicService;
99	        this.ownerMapper = ownerMapper;
100	        this.petMapper = petMapper;
101	        this.visitMapper = visitMapper;
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
107	        Collection<Owner> owners;
108	        if (lastName != null) {
109	            owners = this.clinicService.findOwnerByLastName(lastName);
110	        } else {
111	            owners = this.clinicService.findAllOwners();
112	        }
113	        if (owners.isEmpty()) {
114	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
115	        }
116	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
117	    }
118	
119	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
120	    @Override
121	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
122	        Owner owner = this.clinicService.findOwnerById(ownerId);
123	        if (owner == null) {
124	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
125	        }
126	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
127	    }
128	
129	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
130	    @Override
131	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
132	        // Idempotent create: if this request carries an 'Idempotency-Key' we have already
133	        // seen, return the owner originally created under it (200) rather than creating a
134	        // duplicate. The key is remembered only after a successful create below.
135	        String idempotencyKey = currentIdempotencyKey();
136	        if (idempotencyKey != null) {
137	            Integer existingId = idempotentCreates.get(idempotencyKey);
138	            if (existingId != null) {
139	                Owner existingOwner = this.clinicService.findOwnerById(existingId);
140	                if (existingOwner != null) {
141	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existingOwner), HttpStatus.OK);
142	                }
143	            }
144	        }
145	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
146	        if (normalizedTelephone == null) {
147	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
148	        }
149	        if (isDisposableEmailDomain(ownerFieldsDto.getEmail())) {
150	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
151	        }
152	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
153	        // The owner must supply an address in EITHER form: a non-blank structured
154	        // 'addressLine1' or the flat 'address'. getAddress() prefers the structured
155	        // fields (composing line 1 with an optional line 2) and falls back to the flat
156	        // value; a blank result means neither form was provided. The composed value is
157	        // written back so the persisted flat 'address' stays consistent with it.
158	        String composedAddress = owner.getAddress();
159	        if (composedAddress == null || composedAddress.isBlank()) {
160	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
161	        }
162	        owner.setAddress(composedAddress);
163	        owner.setTelephone(normalizedTelephone);
164	        if (!owner.isPostcodeValidForCity()) {
165	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
166	        }
167	        // The household id is deterministic: it is derived purely from the owner's
168	        // (last name, postcode), so every owner at the same last name and postcode resolves
169	        // to the same value. It is assigned up front, before any duplicate detection, so the
170	        // identity key and the household check below both key off it.
171	        owner.setHouseholdId(householdId(owner.getLastName(), owner.getPostcode()));
172	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
173	        // Consolidated hard-duplicate detection: reject only when the new owner's WHOLE
174	        // identityKey (the SHA-256 over normalizedTelephone|lowerEmail|soundex(lastName))
175	        // equals an existing owner's. Because the telephone is part of the key, two owners
176	        // sharing only a last name and postcode differ here whenever their telephone or email
177	        // differs, and so are both allowed (the second is surfaced as a soft match below). This
178	        // single identity key is now the only 409 duplicate check — the former separate
179	        // household-duplicate block keyed on the computed household id no longer applies.
180	        String identityKey = owner.getIdentityKey();
181	        if (this.clinicService.findAllOwners().stream()
182	            .filter(existing -> !existing.isDeleted())
183	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()))) {
184	            return new ResponseEntity<>(HttpStatus.CONFLICT);
185	        }
186	        // The household id is still computed for household-size and membership-level purposes,
187	        // but sharing it no longer rejects the create.
188	        List<Owner> householdMembers = findHouseholdMembers(owner.getHouseholdId());
189	        if (countOwnersInCity(ownerFieldsDto.getCity()) >= 50) {
190	            return new ResponseEntity<>(HttpStatus.CONFLICT);
191	        }
192	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(LocalDate.now())) {
193	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
194	        }
195	        LocalDate effectiveDate =
196	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
197	        LocalDate registrationDate = toBusinessDay(effectiveDate);
198	        long ownersRegisteredToday = countOwnersRegisteredOn(registrationDate);
199	        if (ownersRegisteredToday >= 100) {
200	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
201	        }
202	        boolean bulkSignupWarning = ownersRegisteredToday > 80;
203	        HttpHeaders headers = new HttpHeaders();
204	        owner.setRegistrationDate(registrationDate);
205	        owner.setCustomerCode(customerCode(owner));
206	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
207	        owner.setBulkSignupWarning(bulkSignupWarning);
208	        // The household size (an input to the membership computation) keys off the computed
209	        // household id: this owner plus everyone already sharing it.
210	        owner.setHouseholdSize(householdMembers.size() + 1);
211	        // Level ceiling: a new owner joining a household they did not explicitly declare
212	        // may not out-rank the household. Cap the derived membership level at one above the
213	        // current maximum among the existing household members; with no existing member no
214	        // cap applies.
215	        if (!sharesHousehold && !householdMembers.isEmpty()) {
216	            int maxHouseholdLevel = householdMembers.stream()
217	                .mapToInt(Owner::getMembershipLevel)
218	                .max()
219	                .orElse(0);
220	            owner.setMembershipLevelCap(maxHouseholdLevel + 1);
221	        }
222	        // Soft-match ("possible duplicate"): a declared household member is not a suspected
223	        // duplicate, so only a non-declared create is scored. A non-declared owner whose
224	        // identity key differs from an existing owner's but whose last name (by Soundex) and
225	        // postcode match is flagged here as a possible duplicate rather than rejected.
226	        Owner possibleDuplicate = sharesHousehold ? null : findPossibleDuplicate(owner);
227	        owner.setPossibleDuplicate(possibleDuplicate != null);
228	        owner.setPossibleDuplicateOf(possibleDuplicate == null ? null : possibleDuplicate.getId());
229	        this.clinicService.saveOwner(owner);
230	        if (idempotencyKey != null) {
231	            idempotentCreates.put(idempotencyKey, owner.getId());
232	        }
233	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
234	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
235	            owner.getMembershipNumber());
236	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
237	        headers.setLocation(UriComponentsBuilder.newInstance()
238	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
239	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
240	    }
241	
242	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
243	    @Override
244	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
245	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
246	        if (currentOwner == null) {
247	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
248	        }
249	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
250	        if (normalizedTelephone == null) {
251	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
252	        }
253	        currentOwner.setAddress(ownerFieldsDto.getAddress());
254	        currentOwner.setCity(ownerFieldsDto.getCity());
255	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
256	        currentOwner.setLastName(ownerFieldsDto.getLastName());
257	        currentOwner.setTelephone(normalizedTelephone);
258	        currentOwner.setEmail(ownerFieldsDto.getEmail());
259	        this.clinicService.saveOwner(currentOwner);
260	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
261	    }
262	
263	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
264	    @Transactional
265	    @Override
266	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
267	        Owner owner = this.clinicService.findOwnerById(ownerId);
268	        if (owner == null) {
269	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
270	        }
271	        // Soft-delete: retain the row and flag it deleted rather than removing it. The owner
272	        // remains readable via GET, and is subsequently ignored by the create endpoint's
273	        // duplicate and identity checks.
274	        owner.setDeleted(true);
275	        this.clinicService.saveOwner(owner);
276	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
277	    }
278	
279	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
280	    @Override
281	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
282	        Owner owner = this.clinicService.findOwnerById(ownerId);
283	        if (owner == null) {
284	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
285	        }
286	        HttpHeaders headers = new HttpHeaders();
287	        Pet pet = petMapper.toPet(petFieldsDto);
288	        owner.setId(ownerId);
289	        pet.setOwner(owner);
290	        pet.getType().setName(null);
291	        this.clinicService.savePet(pet);
292	        PetDto petDto = petMapper.toPetDto(pet);
293	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
294	            .buildAndExpand(pet.getId()).toUri());
295	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
296	    }
297	
298	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
299	    @Override
300	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
301	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
302	        if (currentOwner != null) {
303	            Pet currentPet = this.clinicService.findPetById(petId);
304	            if (currentPet != null) {
305	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
306	                currentPet.setName(petFieldsDto.getName());
307	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
308	                this.clinicService.savePet(currentPet);
309	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
310	            }
311	        }
312	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
313	    }
314	
315	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
316	    @Override
317	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
318	        HttpHeaders headers = new HttpHeaders();
319	        Visit visit = visitMapper.toVisit(visitFieldsDto);
320	        Pet pet = new Pet();
321	        pet.setId(petId);
322	        visit.setPet(pet);
323	        this.clinicService.saveVisit(visit);
324	        VisitDto visitDto = visitMapper.toVisitDto(visit);
325	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
326	            .buildAndExpand(visit.getId()).toUri());
327	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
328	    }
329	
330	
331	    /**
332	     * Normalize a telephone number to E.164 form. Spaces, dashes and brackets are
333	     * stripped. When a leading {@code '+'} and country code are present they are kept;
334	     * otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
335	     * is dropped from the national digits. The result must be a {@code '+'} followed
336	     * by 8 to 15 digits, and is returned as {@code +<digits>}; otherwise {@code null}
337	     * is returned to signal a bad request.
338	     */
339	    /**
340	     * Build the customer code for a newly created owner, formatted
341	     * {@code '<REGION>-<HASH8>'} where {@code REGION} is the region derived from the
342	     * owner's postcode (falling back to the city, or {@code 'UNKNOWN'}, via the same
343	     * derivation the locality uses), and {@code HASH8} is the first eight upper-case
344	     * hex characters of the SHA-256 of the owner's normalized telephone concatenated
345	     * with its last name. This identity carries no sequence number.
346	     */
347	    private String customerCode(Owner owner) {
348	        String region = owner.getLocality();
349	        String hash8 = customerCodeHash(owner.getTelephone(), owner.getLastName());
350	        String base = region + "-" + hash8;
351	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
352	            .map(Owner::getCustomerCode)
353	            .filter(java.util.Objects::nonNull)
354	            .collect(java.util.stream.Collectors.toSet());
355	        if (!existing.contains(base)) {
356	            return base;
357	        }
358	        int n = 2;
359	        while (existing.contains(base + "-" + n)) {
360	            n++;
361	        }
362	        return base + "-" + n;
363	    }
364	
365	    /**
366	     * Compute the {@code HASH8} portion of a customer code: the first eight upper-case
367	     * hex characters of the SHA-256 digest of {@code telephone + lastName} (each
368	     * treated as empty when {@code null}), already in their normalized forms.
369	     */
370	    private String customerCodeHash(String telephone, String lastName) {
371	        String key = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
372	        try {
373	            byte[] digest = MessageDigest.getInstance("SHA-256")
374	                .digest(key.getBytes(StandardCharsets.UTF_8));
375	            StringBuilder sb = new StringBuilder();
376	            for (int i = 0; i < 4; i++) {
377	                sb.append(String.format("%02X", digest[i]));
378	            }
379	            return sb.toString();
380	        }
381	        catch (NoSuchAlgorithmException e) {
382	            throw new IllegalStateException(e);
383	        }
384	    }
385	
386	    /**
387	     * Count the existing owners whose city matches the given one, compared after
388	     * collapsing whitespace and lower-casing. Used to enforce the per-city capacity
389	     * cap: a city that already holds this many owners is at capacity.
390	     */
391	    private long countOwnersInCity(String city) {
392	        String normalizedCity = normalizeForHousehold(city);
393	        return this.clinicService.findAllOwners().stream()
394	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(normalizedCity))
395	            .count();
396	    }
397	
398	    /**
399	     * Count the existing owners whose registration date falls on the given day. Used to
400	     * enforce the per-day create limit: once this many owners have been registered today,
401	     * the day is at capacity and further creates are rejected.
402	     */
403	    private long countOwnersRegisteredOn(LocalDate day) {
404	        return this.clinicService.findAllOwners().stream()
405	            .filter(existing -> day.equals(existing.getRegistrationDate()))
406	            .count();
407	    }
408	
409	    /**
410	     * The fixed public holidays that the business-day roll skips. A registration date
411	     * landing on one of these is treated like a weekend and advanced to the next
412	     * non-holiday business day.
413	     */
414	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
415	        LocalDate.parse("2026-01-01"),
416	        LocalDate.parse("2026-01-26"),
417	        LocalDate.parse("2026-04-25"),
418	        LocalDate.parse("2026-12-25"),
419	        LocalDate.parse("2026-12-28"));
420	
421	    /**
422	     * Roll a registration date forward to the next business day: a date falling on a
423	     * Saturday, Sunday or listed public holiday is advanced one day at a time until it
424	     * lands on a non-holiday weekday, while a plain weekday is returned unchanged.
425	     */
426	    private LocalDate toBusinessDay(LocalDate date) {
427	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
428	            date = date.plusDays(1);
429	        }
430	        return date;
431	    }
432	
433	    private static boolean isWeekend(LocalDate date) {
434	        DayOfWeek dayOfWeek = date.getDayOfWeek();
435	        return dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY;
436	    }
437	
438	    /**
439	     * Find the existing owners that already belong to the same household as the given
440	     * computed household id. Because the household id is derived deterministically from
441	     * the owner's (last name, postcode), this is exactly the set of other owners sharing
442	     * that last name and postcode.
443	     */
444	    private List<Owner> findHouseholdMembers(String householdId) {
445	        if (householdId == null) {
446	            return List.of();
447	        }
448	        return this.clinicService.findAllOwners().stream()
449	            .filter(existing -> !existing.isDeleted())
450	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
451	            .toList();
452	    }
453	
454	    /**
455	     * Find an existing owner that this new owner softly duplicates: one whose last name has
456	     * the same Soundex code and whose postcode matches, but whose whole identity key differs
457	     * (an equal identity key is a hard duplicate, already rejected above with 409). Returns
458	     * the lowest-id such owner, or {@code null} when the new owner has no postcode or no soft
459	     * match exists. Owners flagged deleted are ignored.
460	     */
461	    private Owner findPossibleDuplicate(Owner owner) {
462	        String postcode = owner.getPostcode();
463	        if (postcode == null) {
464	            return null;
465	        }
466	        String soundex = Owner.soundex(owner.getLastName());
467	        String identityKey = owner.getIdentityKey();
468	        return this.clinicService.findAllOwners().stream()
469	            .filter(existing -> !existing.isDeleted())
470	            .filter(existing -> Owner.soundex(existing.getLastName()).equals(soundex)
471	                && postcode.equals(existing.getPostcode())
472	                && !identityKey.equals(existing.getIdentityKey()))
473	            .min(java.util.Comparator.comparing(Owner::getId))
474	            .orElse(null);
475	    }
476	
477	    /**
478	     * Count the existing owners that already share both the given first and last
479	     * name, compared case-insensitively. Used to populate an owner's namesake count
480	     * at creation time, reflecting how many owners with the same name existed before
481	     * this one was created.
482	     */
483	    private int countNamesakes(String firstName, String lastName) {
484	        String normalizedFirstName = normalizeName(firstName);
485	        String normalizedLastName = normalizeName(lastName);
486	        return (int) this.clinicService.findAllOwners().stream()
487	            .filter(existing -> normalizeName(existing.getFirstName()).equals(normalizedFirstName)
488	                && normalizeName(existing.getLastName()).equals(normalizedLastName))
489	            .count();
490	    }
491	
492	    private String normalizeName(String value) {
493	        return value == null ? "" : value.toLowerCase(Locale.ROOT);
494	    }
495	
496	    /**
497	     * Build the deterministic identifier shared by all owners of one household: the first
498	     * 12 hex characters of the SHA-256 digest of {@code normalizedLastName + '|' + postcode}.
499	     * Because it depends only on the (last name, postcode) pair, every owner at the same last
500	     * name and postcode resolves to the same value regardless of creation order.
501	     */
502	    private String householdId(String lastName, String postcode) {
503	        String key = normalizeForHousehold(lastName) + "|" + (postcode == null ? "" : postcode);
504	        try {
505	            byte[] digest = MessageDigest.getInstance("SHA-256")
506	                .digest(key.getBytes(StandardCharsets.UTF_8));
507	            StringBuilder sb = new StringBuilder();
508	            for (int i = 0; i < 6; i++) {
509	                sb.append(String.format("%02x", digest[i]));
510	            }
511	            return sb.toString();
512	        }
513	        catch (NoSuchAlgorithmException e) {
514	            throw new IllegalStateException(e);
515	        }
516	    }
517	
518	    private String normalizeForHousehold(String value) {
519	        if (value == null) {
520	            return "";
521	        }
522	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
523	    }
524	
525	    /** True when the email's domain is on the disposable-provider blocklist. */
526	    private boolean isDisposableEmailDomain(String email) {
527	        if (email == null) {
528	            return false;
529	        }
530	        int at = email.lastIndexOf('@');
531	        if (at < 0 || at == email.length() - 1) {
532	            return false;
533	        }
534	        String domain = email.substring(at + 1).trim().toLowerCase(Locale.ROOT);
535	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
536	    }
537	
538	    /**
539	     * Read the {@code Idempotency-Key} header from the current request, or {@code null}
540	     * when it is absent or blank (the generated API signature does not expose it, so it is
541	     * pulled from the bound request attributes).
542	     */
543	    private String currentIdempotencyKey() {
544	        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes)) {
545	            return null;
546	        }
547	        String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
548	        return (key == null || key.isBlank()) ? null : key;
549	    }
550	
551	    private String normalizeTelephone(String telephone) {
552	        if (telephone == null) {
553	            return null;
554	        }
555	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
556	        String digits;
557	        if (cleaned.startsWith("+")) {
558	            digits = cleaned.substring(1);
559	        } else {
560	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
561	            digits = "61" + national;
562	        }
563	        if (!digits.matches("[0-9]{8,15}")) {
564	            return null;
565	        }
566	        if (!hasValidNationalLength(digits)) {
567	            return null;
568	        }
569	        return "+" + digits;
570	    }
571	
572	    /**
573	     * Validate the national-number length of an E.164 number (the digits, without the
574	     * leading {@code '+'}) against its country code. Australia ({@code '+61'}) requires
575	     * exactly 9 national digits and North America ({@code '+1'}) exactly 10; country
576	     * codes without a known rule are accepted as-is.
577	     */
578	    private boolean hasValidNationalLength(String digits) {
579	        if (digits.startsWith("61")) {
580	            return digits.length() - 2 == 9;
581	        }
582	        if (digits.startsWith("1")) {
583	            return digits.length() - 1 == 10;
584	        }
585	        return true;
586	    }
587	
588	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
589	    @Override
590	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
591	        Owner owner = this.clinicService.findOwnerById(ownerId);
592	        if (owner != null) {
593	            Pet pet = owner.getPet(petId);
594	            if (pet != null) {
595	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
596	            }
597	        }
598	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
599	    }
600	}
